"""Cross-language smoke test: vectors generated by Node must verify in Python."""

import hashlib
import hmac
import json
from pathlib import Path

CONTRACTS = Path(__file__).resolve().parents[2] / "contracts"
CONSTANTS = json.loads((CONTRACTS / "constants.json").read_text(encoding="utf-8"))
VECTORS = json.loads((CONTRACTS / "test_vectors.json").read_text(encoding="utf-8"))

PART_3_1 = {
    "SAFE_MIN_C": 2.0,
    "SAFE_MAX_C": 8.0,
    "WARN_HIGH_C": 7.5,
    "WARN_LOW_C": 2.5,
    "COMP_ON_AT_C": 7.0,
    "COMP_OFF_AT_C": 3.0,
    "COMP_MIN_OFF_S": 60,
    "TELEMETRY_PERIOD_S": 5,
    "BUDGET_S": 3600,
    "DOUBLE_ABOVE_C": 12.0,
    "AT_RISK_PCT": 20,
    "DOOR_ALARM_S": 60,
    "BUFFER_CAPACITY": 720,
    "SYNC_CHUNK": 25,
    "HMAC_WINDOW_S": 30,
    "NONCE_TTL_S": 120,
    "FORECAST_HORIZON_MIN": 30,
}


def test_constants_match_spec():
    assert {k: CONSTANTS[k] for k in PART_3_1} == PART_3_1
    assert set(CONSTANTS["TOPICS"]) == {"telemetry", "event", "sync", "ack", "cmd", "cmdack", "status"}


def test_vector_counts():
    assert (len(VECTORS["hmac"]), len(VECTORS["status"]), len(VECTORS["exposure"])) == (5, 12, 8)


def test_hmac_vectors_verify_in_python():
    for v in VECTORS["hmac"]:
        msg = f"{v['device_id']}|{v['kind']}|{v['ts']}|{v['nonce']}|{v['body']}"
        assert msg == v["signing_string"]
        sig = hmac.new(v["secret"].encode(), msg.encode(), hashlib.sha256).hexdigest()
        assert hmac.compare_digest(sig, v["sig"]), v["name"]


def test_rotate_vectors_seal_and_open_in_python():
    """S7: the virtual node opens what the backend seals, byte for byte with Node and the firmware."""
    from coldchain_tools.envelope import rotate_open, rotate_seal

    assert len(VECTORS["rotate"]) == 2
    for v in VECTORS["rotate"]:
        assert rotate_seal(v["old_secret"], v["new_secret"], v["nonce"]) == (v["ct"], v["tag"])
        assert rotate_open(v["old_secret"], v["nonce"], v["ct"], v["tag"]) == v["new_secret"]
        flipped = ("b" if v["ct"][0] == "a" else "a") + v["ct"][1:]
        assert rotate_open(v["old_secret"], v["nonce"], flipped, v["tag"]) is None
        assert rotate_open(VECTORS["rotate"][0]["new_secret"], v["nonce"], v["ct"], v["tag"]) is None
        assert rotate_open(v["old_secret"], "short", v["ct"], v["tag"]) is None
